import random
import time


class UploadError(Exception):
    """An upload failed after every retry."""


def upload_with_retry(send, chunk, attempts=3, delay=0.5):
    """Send one chunk, retrying transient timeouts with jittered exponential backoff."""
    last_error = None
    for attempt in range(attempts):
        try:
            return send(chunk)
        except TimeoutError as error:
            last_error = error
            if attempt + 1 < attempts:
                time.sleep(random.uniform(0, delay * (2 ** attempt)))
    raise UploadError(f"upload failed after {attempts} attempts") from last_error
